curl -s --variable ca_key@ca.pub --expand-write-out " @cert-authority * {{ca_key}}" -o /dev/null file:////dev/null > known_hosts
ssh-keygen -t ed25519 -N "" -C "" -f other_ca
curl -s --variable ca_key@other_ca.pub --expand-write-out " @cert-authority * {{ca_key}}" -o /dev/null file:////dev/null > other_known_hosts
ssh-keygen -lf host_key.pub > fingerprint.txt
surl --directory site --hostkey host_key --hostcert host_key-cert.pub --authorized-keys alice:client_key.pub --user alice:s3cret scp://127.0.0.1:8080/ &
